"""Refresh the reviewed image API contract or check its generated type aliases."""

import argparse
import json
from datetime import date
from pathlib import Path
from urllib.request import urlopen

ROOT = Path(__file__).resolve().parents[1]
CONTRACT = ROOT / "contracts/gpt-image.json"
TARGET = ROOT / "packages/gpt-image/src/langchain_gpt_image_acedatacloud/_contract.py"


def generate(contract):
    lines = [
        '"""Generated by scripts/sync_gpt_image_contract.py; edit the reviewed contract source."""',
        "",
        "from typing import Literal",
        "",
    ]
    for field, alias in [("model", "ImageModel"), ("quality", "ImageQuality")]:
        values = contract["fields"][field]["enum"]
        if not values or not all(isinstance(value, str) and value for value in values):
            raise ValueError(f"Invalid {field} enum")
        lines.append(f"{alias} = Literal[")
        lines.extend(f"    {json.dumps(value)}," for value in dict.fromkeys(values))
        lines.extend(
            [
                "]",
                "",
            ]
        )
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--refresh",
        action="store_true",
        help="Read the public API contract; never submit an image request",
    )
    parser.add_argument("--check", action="store_true", help="Offline reproducibility check")
    args = parser.parse_args()
    if args.refresh and args.check:
        parser.error("Choose refresh or check")
    contract = json.loads(CONTRACT.read_text())
    if args.refresh:
        with urlopen(contract["source"], timeout=30) as response:
            api = json.load(response)
        schema = api["definition"]["paths"][contract["path"]]["post"]["requestBody"]["content"][
            "application/json"
        ]["schema"]
        contract["captured_at"] = date.today().isoformat()
        contract["required"] = schema.get("required", [])
        contract["fields"] = {key: schema["properties"][key] for key in contract["fields"]}
        CONTRACT.write_text(json.dumps(contract, indent=2) + "\n")
    generated = generate(contract)
    if args.check:
        if TARGET.read_text() != generated:
            raise SystemExit("Image contract types need regeneration")
    else:
        TARGET.write_text(generated)


if __name__ == "__main__":
    main()
